<?php declare(strict_types=1);require dirname(__DIR__,2).'/includes/bootstrap.php';require_permission('hunts.activate');if(is_post()){verify_csrf();try{$result=activate_hunt_for_user((int)input('user_id'),(int)input('hunt_id'),strtoupper((string)input('activation_type')),null,(int)admin()['id']);flash('success',$result['created']?'Hunt activated.':'Activation was already active.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect('/admin/hunts/activations.php');}$hunts=db()->query("SELECT id,title FROM hunts WHERE status='ACTIVE' AND NOW() BETWEEN start_at AND end_at ORDER BY title")->fetchAll();$users=db()->query("SELECT id,name,mobile FROM users WHERE status='ACTIVE' ORDER BY id DESC LIMIT 200")->fetchAll();$items=db()->query('SELECT a.*,u.name user_name,h.title hunt_title,ad.name admin_name FROM hunt_user_activations a JOIN users u ON u.id=a.user_id JOIN hunts h ON h.id=a.hunt_id LEFT JOIN admins ad ON ad.id=a.activated_by ORDER BY a.id DESC LIMIT 200')->fetchAll();$pageTitle='Hunt activations';$pageSubtitle='Online payments are webhook-verified; counter activations are administrator-audited';require APP_ROOT.'/includes/header.php';?><section class="panel"><form method="post" class="filters" data-confirm="Activate this hunt for the selected user?"><?=csrf_field()?><select name="user_id" required><option value="">Select user</option><?php foreach($users as $u):?><option value="<?=e($u['id'])?>"><?=e($u['name'].' · '.$u['mobile'])?></option><?php endforeach?></select><select name="hunt_id" required><option value="">Select hunt</option><?php foreach($hunts as $h):?><option value="<?=e($h['id'])?>"><?=e($h['title'])?></option><?php endforeach?></select><select name="activation_type"><option>COUNTER</option><option>ADMIN</option></select><button class="btn">Activate</button></form><div class="table-wrap"><table><thead><tr><th>User</th><th>Hunt</th><th>Type</th><th>Status</th><th>Admin</th><th>Activated</th></tr></thead><tbody><?php foreach($items as $a):?><tr><td><?=e($a['user_name'])?></td><td><?=e($a['hunt_title'])?></td><td><?=e($a['activation_type'])?></td><td><span class="badge <?=strtolower(e($a['status']))?>"><?=e($a['status'])?></span></td><td><?=e($a['admin_name']??'Payment webhook')?></td><td><?=e($a['activated_at'])?></td></tr><?php endforeach?></tbody></table></div></section><?php require APP_ROOT.'/includes/footer.php';
